# print number who is greater 
p = input("Enter the number p:")
q = input("Enter the number q")
r = input("Enter the number r:")
s = input("Enter the number s:")
if(p>q and p>r and p>s):
    print("P is greater than q, r, s", p)
elif(q>p and q>r and q>s):
    print("q is greater than p, r, s", q)
elif(r>p and r>q and r>s):
    print("r is greater than p, q, s", r)
else:
    print("s is greater than p, q, r", s)


